// Armazenar histórico
let historico = global.get('historico') || [];

historico.push({
    adc: data.adc || 0,
    status: data.status || 'N/A',
    nivel: data.nivel || 'N/A',
    temp: data.temp || 0,
    umid: data.umid || 0,
    timestamp: new Date().toISOString()
});

// Manter últimas 480 leituras (8 horas @ 1min)
while (historico.length > 480) {
    historico.shift();
}

global.set('historico', historico);

// Calcular estatísticas
if (historico.length > 0) {
    let adcs = historico.map(h => h.adc || 0);
    let temps = historico.map(h => h.temp || 0);
    let umids = historico.map(h => h.umid || 0);

    let stats = {
        maxADC: Math.max(...adcs),
        minADC: Math.min(...adcs),
        avgTemp: (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1),
        avgUmid: (umids.reduce((a, b) => a + b, 0) / umids.length).toFixed(1)
    };

    global.set('stats', stats);
}

return msg;

