});

// Mantém apenas últimas 24h (2880 registros @ 30s)
while (historicoAcionamentos.length > 2880) {
    historicoAcionamentos.shift();
}
global.set('historicoAcionamentos', historicoAcionamentos);

// Retorna 4 outputs: janela, ventilador, exaustor, filtro, dados completos
return [
    {payload: automacao.janela || 0},
    {payload: automacao.ventilador || 0},
    {payload: automacao.exaustor || false},
