];

let historico = global.get('historicoAcionamentos') || [];

if (historico.length === 0) {
    return null;
}

// Agrupar por hora (últimas 24h)
let grupos = {};
let agora = new Date();

for (let h = 23; h >= 0; h--) {
    let hora = new Date(agora.getTime() - (h * 3600000));
    let horaKey = hora.getHours();
    grupos[horaKey] = {
        label: horaKey.toString().padStart(2, '0') + ':00',
        janela: 0,
        ventilador: 0,
        exaustor: 0,
        filtro: 0,
        count: 0
    };
}

// Processar dados
historico.forEach(item => {
    let timestamp = new Date(item.timestamp);
    let diff = agora - timestamp;

    // Apenas últimas 24h
    if (diff <= 86400000) {
        let hora = timestamp.getHours();
        if (grupos[hora]) {
            grupos[hora].janela += item.janela || 0;
            grupos[hora].ventilador += (item.ventilador || 0) > 0 ? 1 : 0;
            grupos[hora].exaustor += item.exaustor ? 1 : 0;
            grupos[hora].filtro += (item.filtro || 0) > 512 ? 1 : 0;
            grupos[hora].count++;
        }
    }
});

// Calcular médias e formatar
let series = {
    'Janela (° médio)': [],
    'Ventilador (min)': [],
    'Exaustor (min)': [],
    'Filtro (ciclos)': []
};
let labels = [];

Object.keys(grupos).sort((a, b) => a - b).forEach(hora => {
    let g = grupos[hora];
    labels.push(g.label);

    series['Janela (° médio)'].push(g.count > 0 ? Math.round(g.janela / g.count) : 0);
    series['Ventilador (min)'].push(g.ventilador * 3); // 3min/leitura
    series['Exaustor (min)'].push(g.exaustor * 3);
    series['Filtro (ciclos)'].push(g.filtro);
});

// Preparar mensagens para cada série
let messages = [];
Object.keys(series).forEach(seriesName => {
    labels.forEach((label, idx) => {
        messages.push({
            payload: series[seriesName][idx],
            topic: seriesName,
            categoria: label
        });
    });
});

return [messages];

